control 'sample-01' do
  impact 0.5
  title 'Check /etc/hosts exists and contains localhost'
  desc 'Ensure the /etc/hosts file exists and has an entry for localhost'

  describe file('/etc/hosts') do
    it { should exist }
    it { should be_file }
    its('content') { should match /localhost/ }
  end
end
